const { type } = require('arktype');

// Single expression chain: string -> narrow for all constraints
const username = type('string')
  .narrow((s, ctx) => {
    if (s.length < 3) return ctx.reject('too short');
    if (s.length > 19) return ctx.reject('too long');
    if (!/^[a-zA-Z]/.test(s)) return ctx.reject('must start with a letter');
    if (!/^[a-zA-Z0-9]+$/.test(s)) return ctx.reject('must be alphanumeric');
    return true;
  });

const tests = ['alice123', 'al', 'aaaaaaaaaaaaaaaaaaaa', 'alice!', '1alice'];
for (const t of tests) {
  const r = username(t);
  console.log(t + ':', typeof r === 'string' ? 'valid' : 'invalid');
}
